from collections import deque

def resolve(path, cwd, links):
    if not path.startswith('/'):
        path = cwd.rstrip('/') + '/' + path
        if not path.startswith('/'):
            path = '/' + path

    link_count = 0
    resolved_parts = []
    components = deque(path.split('/'))

    while components:
        comp = components.popleft()
        if comp == '' or comp == '.':
            continue
        if comp == '..':
            if resolved_parts:
                resolved_parts.pop()
            continue

        resolved_parts.append(comp)
        current_path = '/' + '/'.join(resolved_parts)

        if current_path in links:
            link_count += 1
            if link_count > 8:
                return None
            target = links[current_path]
            # remove the link's own name, leaving the directory containing it
            resolved_parts.pop()

            if not target.startswith('/'):
                base = '/' + '/'.join(resolved_parts)
                if base == '/':
                    target_full = '/' + target
                else:
                    target_full = base + '/' + target
            else:
                target_full = target

            new_comps = deque(target_full.split('/'))
            new_comps.extend(components)
            components = new_comps

    if not resolved_parts:
        return '/'
    return '/' + '/'.join(resolved_parts)

